package it.andreademartini.trading.marketdata.ticks;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.math.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static it.andreademartini.trading.marketdata.ticks.MinimumTickResolver.*;
import it.andreademartini.trading.marketdata.PriceAdjustment;
import it.andreademartini.trading.backtest.reboundv3.*;

class MinimumTickResolverTest {
 static final LocalDate DATE=LocalDate.of(2024,1,2),FROM=LocalDate.of(2020,1,1),TO=LocalDate.of(2026,12,31);
 static final String DATASET="fixture-only";
 static BigDecimal b(String v){return new BigDecimal(v);}
 static Instrument instrument(){return new Instrument("TEST",List.of("TEST.US"),"TEST_EXCHANGE","USD","STK");}
 static Rule rule(String id,String source,String domain,List<Band> bands){return new Rule(id,"TEST","TEST_EXCHANGE","USD","STK",FROM,TO,source,"SYNTHETIC TEST FIXTURE, not production metadata",true,domain,domain.equals("DATASET")?DATASET:null,bands);}
 static Rule rule(String id,String source,String tick){return rule(id,source,"RAW",List.of(new Band(BigDecimal.ZERO,b(tick))));}
 static Catalog catalog(List<Rule> rules,List<PriceBasis> bases){return new Catalog("TEST/1",List.of(instrument()),rules,bases);}
 static MinimumTickResolver resolver(List<Rule> rules){return new MinimumTickResolver(catalog(rules,List.of()),Map.of(),"UNSPECIFIED");}
 static Resolution resolve(MinimumTickResolver r,String p,int ticks){return r.resolve("TEST",DATE,b(p),PriceAdjustment.RAW,DATASET,ticks);}
 @Test void exactTickAndNonAlignedPricesUseStrictSuccessor(){var r=resolver(List.of(rule("r","SAVED_MARKET_RULE","0.01")));assertEquals(0,b("102.01").compareTo(resolve(r,"102.00",1).buyStopTrigger()));assertEquals(0,b("102.01").compareTo(resolve(r,"102.005",1).buyStopTrigger()));assertEquals(0,b("102.02").compareTo(resolve(r,"102.005",2).buyStopTrigger()));assertEquals("SAVED_MARKET_RULE",resolve(r,"102",1).tickSource());}
 @Test void boundariesUseFinalBandAndBufferCountsValidGridSteps(){var r=resolver(List.of(rule("tiered","INSTRUMENT_MASTER","RAW",List.of(new Band(BigDecimal.ZERO,b("0.0001")),new Band(b("1"),b("0.01")),new Band(b("100"),b("0.05"))))));assertEquals(0,b("1").compareTo(resolve(r,"0.99999",1).buyStopTrigger()));assertEquals(0,b("0.01").compareTo(resolve(r,"0.99999",1).minimumTick()));assertEquals(0,b("100.05").compareTo(resolve(r,"99.99",2).buyStopTrigger()));assertEquals(0,b("100.05").compareTo(resolve(r,"100.03",1).buyStopTrigger()));}
 @Test void hierarchyNeverSubstitutesOverrideForValidatedMetadata(){var c=catalog(List.of(rule("saved","SAVED_MARKET_RULE","0.05"),rule("master","INSTRUMENT_MASTER","0.01"),rule("dataset","DATASET_METADATA","DATASET",List.of(new Band(BigDecimal.ZERO,b("0.001"))))),List.of());var r=new MinimumTickResolver(c,Map.of("TEST",b("0.5")),"RAW");assertEquals("dataset",resolve(r,"102",1).tickRuleId());assertEquals(0,b("102.001").compareTo(resolve(r,"102",1).buyStopTrigger()));}
 @Test void aliasesAreExplicitAndIdentityIsNotGuessed(){var r=resolver(List.of(rule("r","SAVED_MARKET_RULE","0.01")));assertEquals("TEST.US",r.resolve("TEST.US",DATE,b("10"),PriceAdjustment.RAW,DATASET,1).symbol());assertThrows(TickException.class,()->r.resolve("OTHER.US",DATE,b("10"),PriceAdjustment.RAW,DATASET,1));var wrong=new Rule("wrong","TEST","OTHER_EXCHANGE","USD","STK",FROM,TO,"SAVED_MARKET_RULE","TEST ONLY",true,"RAW",null,List.of(new Band(BigDecimal.ZERO,b(".01"))));assertThrows(TickException.class,()->resolve(resolver(List.of(wrong)),"10",1));}
 @Test void explicitOverridesRequireIdentityAndDomainAndPositiveValues(){var c=catalog(List.of(),List.of());assertThrows(IllegalArgumentException.class,()->new MinimumTickResolver(c,Map.of("TEST",b("-1")),"RAW"));var r=new MinimumTickResolver(c,Map.of("TEST",b(".05")),"RAW");assertEquals("EXPLICIT_OVERRIDE",resolve(r,"10",1).tickSource());assertEquals(0,b("10.05").compareTo(resolve(r,"10",1).buyStopTrigger()));assertThrows(TickException.class,()->resolve(new MinimumTickResolver(c,Map.of("TEST",b(".01")),"UNSPECIFIED"),"10",1));assertThrows(TickException.class,()->new MinimumTickResolver(Catalog.empty(),Map.of("UNKNOWN",b(".01")),"RAW"));}
 @Test void missingRulesFailWithoutFallbackAndValidityIsHistorical(){assertThrows(TickException.class,()->resolve(resolver(List.of()),"10",1));var r=resolver(List.of(rule("r","SAVED_MARKET_RULE",".01")));assertThrows(TickException.class,()->r.resolve("TEST",FROM.minusDays(1),b("10"),PriceAdjustment.RAW,DATASET,1));assertThrows(IllegalArgumentException.class,()->rule("bound","DATASET_METADATA","RAW",List.of(new Band(BigDecimal.ZERO,b(".01")))));}
 @Test void adjustedPricesRequireVerifiedDatasetBoundFactors(){var rule=rule("raw","SAVED_MARKET_RULE",".01");var plain=resolver(List.of(rule));assertThrows(TickException.class,()->plain.resolve("TEST",DATE,b("10"),PriceAdjustment.ADJUSTED,DATASET,1));var basis=new PriceBasis("TEST",DATASET,FROM,TO,"SPLIT_ADJUSTED",b("10"),"TEST fixture split factor",true);var r=new MinimumTickResolver(catalog(List.of(rule),List.of(basis)),Map.of(),"UNSPECIFIED");var resolved=r.resolve("TEST",DATE,b("10"),PriceAdjustment.ADJUSTED,DATASET,1);assertEquals(0,b("10.001").compareTo(resolved.buyStopTrigger()));assertEquals(0,b(".001").compareTo(resolved.minimumTick()));assertEquals("EXACT_RAW_TO_DATASET_TRANSFORMATION",resolved.adjustedPriceCompatibility());assertThrows(TickException.class,()->r.resolve("TEST",DATE,b("10"),PriceAdjustment.ADJUSTED,"different-dataset",1));}
 @Test void dividendAdjustmentIsExplicitAndNonTerminatingConversionsReject(){for(String factor:List.of("2.5","3")){var basis=new PriceBasis("TEST",DATASET,FROM,TO,"TOTAL_RETURN_ADJUSTED",b(factor),"TEST fixture dividend adjustment",true);var r=new MinimumTickResolver(catalog(List.of(rule("r","SAVED_MARKET_RULE",".01")),List.of(basis)),Map.of(),"UNSPECIFIED");if(factor.equals("3"))assertTrue(assertThrows(TickException.class,()->r.resolve("TEST",DATE,b("10"),PriceAdjustment.ADJUSTED,DATASET,1)).getMessage().contains("NON_TERMINATING"));else assertEquals(0,b("10.004").compareTo(r.resolve("TEST",DATE,b("10"),PriceAdjustment.ADJUSTED,DATASET,1).buyStopTrigger()));}}
 @Test void conflictingRulesAndInvalidBandsAreRejected(){assertThrows(IllegalArgumentException.class,()->new Band(BigDecimal.ZERO,BigDecimal.ZERO));assertThrows(TickException.class,()->resolve(resolver(List.of(rule("a","SAVED_MARKET_RULE",".01"),rule("b","SAVED_MARKET_RULE",".02"))),"10",1));}
 @Test void configurationRoundTripPreservesRulesOverridesAndHash(@TempDir Path temp)throws Exception{var json=TrendReboundV3Store.JSON;var node=(com.fasterxml.jackson.databind.node.ObjectNode)json.valueToTree(TrendReboundV3Configuration.defaults());node.set("minimumTickMetadata",json.valueToTree(catalog(List.of(rule("r","INSTRUMENT_MASTER",".01")),List.of())));node.set("minimumTickSizes",json.valueToTree(Map.of("TEST",b("0.0000000001234567890123456789"))));node.put("minimumTickOverrideDomain","RAW");var c=json.treeToValue(node,TrendReboundV3Configuration.class);c.validate();var file=temp.resolve("catalog.json");json.writeValue(file.toFile(),c);assertTrue(json.readTree(file.toFile()).path("minimumTickSizes").path("TEST").isTextual());var restored=json.readValue(file.toFile(),TrendReboundV3Configuration.class);assertEquals(c,restored);assertEquals(V3TickSupport.hash(c),V3TickSupport.hash(restored));assertFalse(restored.minimumTickMetadata().rules().isEmpty());assertEquals("FAIL_FAST",restored.minimumTickResolutionPolicy());}
}
